/**
 * Every live issue of a project, in number order, labels included. Unpaged:
 * cloning has to walk the whole project, not its first page.
 */
export async function listLiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(issues.number, issues.id)
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );

  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

/** Cascade behind `ProjectService.archiveProject`; returns the row count. */

